  * This wrapper renames them via suggestName / the port map so that the
  * Chisel-side API uses the friendlier `enable` / `te` names while still
  * resolving to the correct SV port names.
  */
class ClockGate extends BlackBox with HasBlackBoxPath {
  val io = IO(new Bundle {
    val clk_i  = Input(Clock())
    val en_i   = Input(Bool())
    val test_en_i = Input(Bool())
    val clk_o  = Output(Clock())
  })

  // Expose friendly aliases so callers can write cg.io.enable / cg.io.te
  // via a thin wrapper, see ClockGateWrapper below.
}

