package coralnpu

import chisel3._
import chisel3.util._
import bus._

/** AXI-accessible CSR block for the CoralNPU.
  *
  * Exposes a set of control and status registers over a narrow AXI slave
  * interface.  Software reads/writes these registers to control and monitor
  * the NPU core.
  *
  * Register map (64-bit AXI bus, byte-addressed):
  *   Addr 0x0 – Control word:
  *     bits[31:0]  – control register (bit 0 = cg, bit 1 = reset)
  *     bits[63:32] – NOT USED at this address
  *   Addr 0x4 – pcStart register (32-bit, stored in data[63:32] of 64-bit bus)
  *   Addr 0x100 – CoralNPU status CSR (read-only, coralnpu_csr.value(0))
  *
  * All other addresses return SLVERR on write and 0 on read.
  */
class CoreAxiCSR(p: Parameters) extends Module {

  val DataBits  = p.csrDataBits  // 64
  val DataBytes = DataBits / 8   // 8
  val AddrBits  = p.axi2AddrBits // 32
  val IdBits    = p.axi2IdBits   // 4

  val io = IO(new Bundle {
    /** AXI4 slave port (software master → DUT slave). */
    val axi  = Flipped(new AxiMasterIO(AddrBits, DataBits, IdBits))

    // Status inputs from the core
    val internal     = Input(Bool())
    val halted       = Input(Bool())
    val fault        = Input(Bool())
    val coralnpu_csr = Input(new CoralNPUCsr)

    // Control outputs to the core
    val cg      = Output(Bool())
    val reset   = Output(Bool())
    val pcStart = Output(UInt(32.W))
  })

  // -------------------------------------------------------------------------
  // Control registers (software-writable)
  // -------------------------------------------------------------------------
  val cgReg      = RegInit(true.B)   // default: clock gate enabled
  val resetReg   = RegInit(true.B)   // default: core held in reset
  val pcStartReg = RegInit(0.U(32.W))

  io.cg      := cgReg
  io.reset   := resetReg
  io.pcStart := pcStartReg

  // -------------------------------------------------------------------------
  // AXI write path
  // -------------------------------------------------------------------------
  // Latch address and data when both arrive.
  val writeAddrValid = RegInit(false.B)
  val writeDataValid = RegInit(false.B)
  val writeAddr      = Reg(UInt(AddrBits.W))
  val writeAddrId    = Reg(UInt(IdBits.W))
  val writeData      = Reg(UInt(DataBits.W))
  val writeStrb      = Reg(UInt(DataBytes.W))

  // Address channel: always ready
  io.axi.write.addr.ready := !writeAddrValid || writeDataValid
  when(io.axi.write.addr.valid && io.axi.write.addr.ready) {
    writeAddrValid := true.B
    writeAddr      := io.axi.write.addr.bits.addr
    writeAddrId    := io.axi.write.addr.bits.id
  }

  // Data channel: always ready
  io.axi.write.data.ready := !writeDataValid || writeAddrValid
  when(io.axi.write.data.valid && io.axi.write.data.ready) {
    writeDataValid := true.B
    writeData      := io.axi.write.data.bits.data
    writeStrb      := io.axi.write.data.bits.strb
  }

  // Response channel: issue response once both addr and data are latched
  val pendingWrite  = writeAddrValid && writeDataValid
  val writeRespValid = RegInit(false.B)
  val writeRespId    = Reg(UInt(IdBits.W))
  val writeRespCode  = Reg(UInt(2.W))  // 0 = OKAY, 2 = SLVERR

  io.axi.write.resp.valid      := writeRespValid
  io.axi.write.resp.bits.id    := writeRespId
  io.axi.write.resp.bits.resp  := writeRespCode

  when(pendingWrite && !writeRespValid) {
    writeAddrValid := false.B
    writeDataValid := false.B

    writeRespId    := writeAddrId
    writeRespValid := true.B

    // Decode address and write register
    // addr 0x0  : control register
    //   data[0]   = cg
    //   data[1]   = reset
    // addr 0x4  : pcStart (data[63:32] of 64-bit bus)
    // addr 0x100+: read-only → SLVERR
    val addr = writeAddr
    when(addr === 0x0.U) {
      writeRespCode := 0.U  // OKAY
      // Extract from data[31:0]
      val ctrl = writeData(31, 0)
      cgReg    := ctrl(0)
      resetReg := ctrl(1)
    }.elsewhen(addr === 0x4.U) {
      writeRespCode := 0.U  // OKAY
      // pcStart is in data[63:32]
      pcStartReg := writeData(63, 32)
    }.otherwise {
      writeRespCode := 2.U  // SLVERR
    }
  }

  when(writeRespValid && io.axi.write.resp.ready) {
    writeRespValid := false.B
  }

  // -------------------------------------------------------------------------
  // AXI read path
  // -------------------------------------------------------------------------
  val readAddrValid = RegInit(false.B)
  val readAddr      = Reg(UInt(AddrBits.W))
  val readAddrId    = Reg(UInt(IdBits.W))

  // Address channel: ready when not holding a pending read
  io.axi.read.addr.ready := !readAddrValid
  when(io.axi.read.addr.valid && io.axi.read.addr.ready) {
    readAddrValid := true.B
    readAddr      := io.axi.read.addr.bits.addr
    readAddrId    := io.axi.read.addr.bits.id
  }

  // Data channel: return data one cycle after capturing address
  val readDataValid = RegInit(false.B)
  val readData      = Reg(UInt(DataBits.W))
  val readDataId    = Reg(UInt(IdBits.W))

  io.axi.read.data.valid       := readDataValid
  io.axi.read.data.bits.data   := readData
  io.axi.read.data.bits.last   := true.B
  io.axi.read.data.bits.resp   := 0.U  // always OKAY
  io.axi.read.data.bits.id     := readDataId

  when(readAddrValid && !readDataValid) {
    readAddrValid := false.B
    readDataValid := true.B
    readDataId    := readAddrId

    // Decode address
    // addr 0x0  : data[31:0] = control, data[63:32] = 0
    // addr 0x4  : data[63:32] = pcStart, data[31:0] = 0
    // addr 0x100: data[31:0] = coralnpu_csr.value(0)
    val addr = readAddr
    when(addr === 0x0.U) {
      readData := Cat(0.U(32.W), 0.U(30.W), resetReg, cgReg)
    }.elsewhen(addr === 0x4.U) {
      readData := Cat(pcStartReg, 0.U(32.W))
    }.elsewhen(addr === 0x100.U) {
      readData := Cat(0.U(32.W), io.coralnpu_csr.value(0))
    }.otherwise {
      readData := 0.U
    }
  }

  when(readDataValid && io.axi.read.data.ready) {
    readDataValid := false.B
  }
}

