import bus._

/** Instruction-bus to AXI4 adapter (read-only).
  *
  * Translates a simple IBus (valid/ready/addr/rdata) request into a
  * single-beat AXI4 read transaction on the wide AXI master port.
  *
  * The IBus interface:
  *   valid  (output): DUT wants to fetch instructions
  *   ready  (input) : instruction data is available
  *   addr   (output): fetch address (aligned to fetch-line)
  *   rdata  (input) : fetch-line data (p.fetchDataBits wide)
  *
  * State machine: IDLE → READ_ADDR → READ_DATA → IDLE
  */
class IBus2Axi(p: Parameters) extends Module {
  val io = IO(new Bundle {
    val ibus = new IBus
    val axi  = new AxiMasterIO(p.axi2AddrBits, p.fetchDataBits, p.axi2IdBits)
  })

  val sIdle     = 0.U(2.W)
  val sReadAddr = 1.U(2.W)
  val sReadData = 2.U(2.W)

  val state    = RegInit(sIdle)
  val regAddr  = Reg(UInt(32.W))

  // Default outputs
  io.ibus.ready := false.B
  io.ibus.rdata := 0.U

  io.axi.read.addr.valid       := false.B
  io.axi.read.addr.bits.addr   := regAddr
  io.axi.read.addr.bits.size   := log2Ceil(p.fetchDataBits / 8).U(3.W)
  io.axi.read.addr.bits.len    := 0.U
  io.axi.read.addr.bits.id     := 0.U
  io.axi.read.addr.bits.burst  := 1.U  // INCR
  io.axi.read.addr.bits.lock   := 0.U
  io.axi.read.addr.bits.cache  := 0.U
  io.axi.read.addr.bits.prot   := 0.U
  io.axi.read.addr.bits.qos    := 0.U
  io.axi.read.data.ready       := true.B

  // Write channel not used - tie off
  io.axi.write.addr.valid      := false.B
  io.axi.write.addr.bits       := 0.U.asTypeOf(new AxiWriteAddrChannel(p.axi2AddrBits, p.axi2IdBits))
  io.axi.write.data.valid      := false.B
  io.axi.write.data.bits       := 0.U.asTypeOf(new AxiWriteDataChannel(p.fetchDataBits))
  io.axi.write.resp.ready      := false.B

  switch(state) {
    is(sIdle) {
      when(io.ibus.valid) {
        regAddr := io.ibus.addr
        state   := sReadAddr
      }
    }
    is(sReadAddr) {
      io.axi.read.addr.valid := true.B
      when(io.axi.read.addr.ready) {
        state := sReadData
      }
    }
    is(sReadData) {
      io.axi.read.data.ready := true.B
      when(io.axi.read.data.valid) {
        io.ibus.ready := true.B
        io.ibus.rdata := io.axi.read.data.bits.data
        state         := sIdle
      }
    }
  }
}

object EmitIBus2Axi extends App {
  import circt.stage.ChiselStage
  ChiselStage.emitSystemVerilog(new IBus2Axi(new Parameters), args)
}

